/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"ableton-level-6","number":6,"title":"MIDI Tools Grooves Tuning MPE","skillBand":"Textbook","duration":"From the course textbook","summary":"- Gate ID: ableton-gate-c - Prerequisites: Module 5 (Sections 5.1–5.3) and Module 6 (Sections 6.1–6.4)","modules":[{"id":"ableton-m-GC-1","code":"GC","title":"Readiness Assessment: Gate C","blurb":"- Gate ID: ableton-gate-c - Prerequisites: Module 5 (Sections 5.1–5.3) and Module 6 (Sections 6.1–6.4)","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-gate-c","title":"Section overview","blocks":[{"type":"step","title":"Audio Elasticity, MIDI Manipulation & Micro-Timing Mastery","blocks":[{"type":"heading","text":"Assessment Overview","level":3},{"type":"list","items":["<strong>Gate ID:</strong> <code>ableton-gate-c</code>","<strong>Prerequisites:</strong> Module 5 (Sections 5.1–5.3) and Module 6 (Sections 6.1–6.4)","<strong>Evaluation Format:</strong> Deterministic Self-Assessment Protocol (Direct execution in Ableton Live 12 Standard)","<strong>Objective:</strong> Verify advanced competency in audio warping across distinct algorithms, algorithmic MIDI generation and transformation, per-note MPE editing, Groove Pool commitment, and microtonal scale configuration."],"ordered":false},{"type":"heading","text":"Verification Drill Protocol","level":3},{"type":"prose","html":"Execute the following four operational drills in Ableton Live 12 Standard:"},{"type":"heading","text":"Drill 1: Full-Length Audio Warping & Algorithm Selection","level":4},{"type":"list","items":["Import an un-warped audio track or multi-bar rhythmic loop into an audio track.","Locate the first musical downbeat transient, right-click, and select <strong>Set 1.1.1 Here</strong>.","Pin warp markers at bars <code>2.1.1</code>, <code>5.1.1</code>, and <code>9.1.1</code> to align the audio to the project grid.","Set the Warp Mode to <strong>Beats</strong> for percussive stems, or <strong>Complex Pro</strong> for dense polyphonic audio, adjusting Formant parameters to eliminate artifacts.","Right-click the warped audio clip and execute <strong>Extract Groove(s)</strong> to capture its rhythmic feel in the Groove Pool."],"ordered":true},{"type":"heading","text":"Drill 2: Algorithmic Harmony & MIDI Transformations","level":4},{"type":"list","items":["Create a MIDI track hosting <strong>Drift</strong> or <strong>Operator</strong>.","Open an empty 4-bar MIDI clip. In the Control Bar, set Global Scale to <code>G Minor</code>.","In Clip View, navigate to <strong>Generators -&gt; Stacks</strong>. Generate an 8-chord harmonic progression constrained to G Minor.","Navigate to <strong>Transformations -&gt; Strum</strong>. Apply an offset of 15ms to create an organic keyboard roll.","Navigate to <strong>Transformations -&gt; Velocity Shaper</strong>. Apply a dynamic curve across the phrase."],"ordered":true},{"type":"heading","text":"Drill 3: MPE Per-Note Expression Drawing","level":4},{"type":"list","items":["In the active Drift chord clip, open the <strong>Expression Tab</strong> in Clip View.","Select the <code>Pitch</code> lane. Select the middle note of the third chord and draw a +2 semitone pitch bend that resolves back to pitch, leaving root and top voices unchanged.","Select the <code>Pressure</code> lane. Draw a crescendo pressure ramp on the root note.","In Drift, map Pressure to Filter Cutoff and confirm per-note expressive motion during polyphonic playback."],"ordered":true},{"type":"heading","text":"Drill 4: Groove Assignment & Committing","level":4},{"type":"list","items":["Create a 1/16th-note straight hi-hat pattern on a Drum Rack track.","Assign the extracted groove from Drill 1 (or an MPC Swing template from the Core Library) to the clip's <strong>Groove Chooser</strong>.","Adjust the Timing slider in the Groove Pool to <code>75%</code>.","Click the <strong>Commit</strong> button in Clip View. Verify that the MIDI note positions visibly shift to reflect the groove's micro-timing offsets."],"ordered":true}]}],"minutes":8},{"id":"ableton-gate-c-2","title":"C Verification Checklist & Sign-Off","blocks":[{"type":"step","title":"C Verification Checklist & Sign-Off","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[GATE C PASS CRITERIA]\n[ ] Drill 1 Complete: Audio loop manually warped to rigid metric grid; groove extracted.\n[ ] Drill 2 Complete: Chord progression generated via Stacks; transformed with Strum and Velocity Shaper.\n[ ] Drill 3 Complete: MPE per-note pitch bend and pressure drawn and verified in Drift.\n[ ] Drill 4 Complete: Groove template applied and permanently committed to MIDI note data.</pre>"},{"type":"prose","html":"<strong>Status:</strong> When all criteria are checked, the student is certified for Module 7: Record, Capture, Comp, Bounce, Route &amp; Mix."}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-6-1-2","code":"6.1","title":"MIDI, Tools, Grooves, Tuning & MPE","blurb":"- Section ID: ableton-sec-6-1 - Lessons Included: ableton-l6-1-1, ableton-l6-1-2, ableton-l6-1-3, ableton-l6-1-4","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l6-1-1","title":"Section overview","blocks":[{"type":"step","title":"Section 6.1 — The MIDI Note Editor, Note Dynamics & Multi-Clip Editing","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-6-1</code>","<strong>Lessons Included:</strong> <code>ableton-l6-1-1</code>, <code>ableton-l6-1-2</code>, <code>ableton-l6-1-3</code>, <code>ableton-l6-1-4</code>","<strong>Target Skill Band:</strong> MIDI Sequencing &amp; Precision Note Editing","<strong>Manual Spine References:</strong> Chapter 10 (<em>Editing MIDI: 10.1–10.8</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard MIDI Note Editor"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Operate the MIDI Note Editor Interface:</strong> Navigate the pitch ruler, beat ruler, Draw Mode (<code>B</code>), note audition preview (headphones icon), and adaptive grid divisions.","<strong>Execute Note Geometry Operations:</strong> Select, transpose (<code>Up</code>/<code>Down</code>), fine-nudge, resize durations, stretch note selections, and deactivate/mute notes (<code>0</code>) without deleting them.","<strong>Program Note Probability &amp; Velocity Deviations:</strong> Sculpt velocity envelopes in the velocity lane and program <strong>Probability Chance</strong> percentages (0% to 100%) and <strong>Velocity Range</strong> bounds for humanized stochastic playback.","<strong>Utilize Scale Highlighting &amp; Fold Modes:</strong> Apply scale-aware highlighting, engage the <strong>Scale Fold</strong> view, and engage the <strong>Drum Fold</strong> view to isolate active drum pad rows.","<strong>Execute Multi-Clip MIDI Editing:</strong> Select and edit multiple MIDI clips simultaneously across different tracks in Session or Arrangement View."],"ordered":true}]}],"minutes":8},{"id":"ableton-l6-1-1-2","title":"6.1.1 / 6.1.2: Editor Topology, Navigation & Note Geometry","blocks":[{"type":"step","title":"1.1 The MIDI Note Editor Anatomy","blocks":[{"type":"prose","html":"Opening a MIDI clip in Clip View (<code>Shift+Tab</code>) displays the piano roll matrix:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────────────────────────────────┐\n│                                       MIDI NOTE EDITOR TOPOLOGY                                         │\n├───────────────────┬─────────────────────────────────────────────────────────────────────────────────────┤\n│ 1. PITCH RULER    │ 2. NOTE GRID / PIANO ROLL (Bars &amp; Beats)                                            │\n├───────────────────┼─────────────────────────────────────────────────────────────────────────────────────┤\n│ [Fold] [Scale]    │ Bar 1.1         1.2         1.3         1.4         2.1                             │\n│ G3 ───────────────┼─────────────[=======Note=======]────────────────────                                │\n│ F3 ───────────────┼─────────────────────────────────[===Note===]────────                                │\n│ E3 (In Scale) ────┼─[===Note===]────────────────────────────────────────                                │\n│ C3 (Root Key) ────┼─[===============================Note===============]                                │\n├───────────────────┼─────────────────────────────────────────────────────────────────────────────────────┤\n│ 3. VELOCITY LANE  │   | (100)      | (85)        | (112)     | (70)     |                               │\n├───────────────────┼─────────────────────────────────────────────────────────────────────────────────────┤\n│ 4. CHANCE / PROB. │   100%         100%          75%         40%        100%                            │\n└───────────────────┴─────────────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"1.2 Note Creation & Edit Mechanics","blocks":[{"type":"list","items":["<strong>Draw Mode (<code>B</code>):</strong> Toggles the pencil cursor. Clicking/dragging draws notes matching the active grid subdivision.","<strong>Selection / Pointer Tool (<code>B</code> toggled OFF):</strong> Double-clicking an empty grid slot creates a note; clicking existing notes selects them; dragging notes moves them in pitch/time.","<strong>Audition Headphones Toggle:</strong> Located at the top of the piano roll ruler. When lit blue, selecting or moving notes plays the synth voice in real time.","<strong>Deactivating / Muting Notes (<code>0</code>):</strong> Select any note and press <code>0</code>. The note turns light gray and becomes silent during playback, allowing non-destructive A/B comparison without deleting note data.","<strong>Note Stretch Handles:</strong> When multiple notes are selected, dragging the white stretch markers on either edge scales the relative rhythmic duration of the entire phrase."],"ordered":false}]}],"minutes":8},{"id":"ableton-l6-1-3","title":"6.1.3: Velocity, Probability & Scale Awareness","blocks":[{"type":"step","title":"2.1 Velocity Dynamics & Velocity Deviation Ranges","blocks":[{"type":"prose","html":"In the Velocity Lane at the bottom of the editor:"},{"type":"list","items":["<strong>Velocity Value (1 to 127):</strong> Drag vertical stalks to set explicit MIDI note velocity.","<strong>Velocity Deviation Range (Live 12):</strong> Holding <code>Ctrl</code> while dragging a velocity marker defines a randomized min/max range (e.g., 90 ± 15). Every time the note triggers, Live calculates a random velocity within those mathematical bounds, introducing organic dynamic variation."],"ordered":false}]},{"type":"step","title":"2.2 Note Probability (Chance) Lane","blocks":[{"type":"list","items":["<strong>Probability (0% to 100%):</strong> Sets the mathematical likelihood of the note triggering upon loop playback.","<strong>Stochastic Pattern Design:</strong> Setting ghost snares to 45% chance and high-hat roll flourishes to 60% chance creates complex, evolving drum patterns that never repeat identically."],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                     VELOCITY DEVIATION &amp; PROBABILITY                        │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  NOTE DYNAMICS:                                                             │\n│  • Target Velocity: 100                                                     │\n│  • Velocity Range:  [-15 to +15] ──► Produces values between 85 and 115.    │\n│  • Probability:     75%          ──► Note triggers on 3 out of 4 passes.    │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"2.3 Scale Awareness & Fold Topologies","blocks":[{"type":"list","items":["<strong>Scale Highlighting:</strong> When <strong>Scale</strong> is active in the Control Bar, valid scale degrees are highlighted in orange/white along the pitch ruler, while out-of-scale chromatic notes appear shaded.","<strong>Scale Fold:</strong> Pressing the <strong>Fold</strong> button when Scale is active collapses the piano roll, hiding all out-of-scale chromatic rows entirely.","<strong>Drum Fold:</strong> When editing a Drum Rack MIDI clip, Fold hides all 128 standard MIDI rows except the specific pad rows that contain loaded drum samples."],"ordered":true}]}],"minutes":8},{"id":"ableton-l6-1-4","title":"6.1.4: Multi-Clip Editing & Clip Transforms","blocks":[{"type":"step","title":"6.1.4: Multi-Clip Editing & Clip Transforms","blocks":[{"type":"heading","text":"3.1 Multi-Clip MIDI Editing Topology","level":4},{"type":"prose","html":"Selecting multiple MIDI clips across different tracks (by holding <code>Ctrl</code> or <code>Shift</code>) loads all selected clips into a single unified MIDI Note Editor:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                         MULTI-CLIP EDITING TOPOLOGY                         │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  Clip Focus Chooser: [ Track 1: Bass (Blue) ] [ Track 2: Lead (Orange) ]   │\n│                                                                             │\n│  G3 ─────────────── [ Lead Note (Orange) ] ─────────────────────────────────│\n│  E3 ─────────────── [ Lead Note (Orange) ] ─────────────────────────────────│\n│  C2 ─────────────── [ Bass Note (Blue)   ] ─────────────────────────────────│\n│                                                                             │\n│  • Color-Coded Notes: Each track's notes inherit their clip/track color.    │\n│  • Active Focus: Click any note to bring that track's clip into focus.      │\n│  • Visual Harmonic Alignment: Lock bass fundamentals directly beneath lead  │\n│    melodies without switching views.                                        │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Programming and Humanizing a Drum Pattern:</strong>","Create a Drum Rack track. Double-click an empty Session slot to create a 1-bar clip.","Press <code>B</code> to enable Draw Mode. Draw a 4-on-the-floor kick on <code>C1</code>, snares on <code>D1</code> (beats 2 and 4), and 1/16th hi-hats on <code>F#1</code>.","Open the <strong>Velocity Lane</strong>. Add an accent curve: set downbeat hats to velocity 105, offbeat hats to 70.","Open the <strong>Chance Lane</strong>. Select ghost snare notes at beats 2.4 and 4.4; set their Probability to <code>50%</code>.","Loop the clip for 8 bars. Confirm organic rhythmic variation.","<strong>Multi-Clip Bass and Lead Harmonic Alignment:</strong>","Create a Bass MIDI track hosting Drift; create a Lead MIDI track hosting Operator.","Draw an 8-bar chord progression on the Lead track.","Hold <code>Ctrl</code> and select both the Lead clip and an empty Bass clip.","In the unified Multi-Clip editor, draw bass fundamental notes on the blue track directly aligned beneath the root notes of the orange chord progression."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 6.0]\n[ ] Fluent with Draw Mode (B), Note Muting (0), and Note Auditioning.\n[ ] Programmed Velocity Deviation ranges and Note Probability percentages.\n[ ] Utilized Scale Highlighting and Fold view modes.\n[ ] Executed Multi-Clip editing across two distinct instrument tracks simultaneously.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 10 (<em>Editing MIDI: 10.1–10.8</em>).","<strong>Ableton Knowledgebase:</strong> <em>MIDI Note Editor in Live 12</em>, <em>Using Note Chance and Velocity Range</em>, <em>Multi-Clip Editing Guide</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-6-2-3","code":"6.2","title":"MIDI, Tools, Grooves, Tuning & MPE","blurb":"- Section ID: ableton-sec-6-2 - Lessons Included: ableton-l6-2-1, ableton-l6-2-2, ableton-l6-2-3, ableton-l6-2-4","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l6-2-1","title":"Section overview","blocks":[{"type":"step","title":"Section 6.2 — MIDI Tools: Transformations & Generators","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-6-2</code>","<strong>Lessons Included:</strong> <code>ableton-l6-2-1</code>, <code>ableton-l6-2-2</code>, <code>ableton-l6-2-3</code>, <code>ableton-l6-2-4</code>","<strong>Target Skill Band:</strong> Algorithmic MIDI Composition &amp; Note Manipulation","<strong>Manual Spine References:</strong> Chapter 11 (<em>MIDI Tools: 11.1–11.3</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Native MIDI Tools Suite (17 Standard Tools)"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Differentiate MIDI Tools from MIDI Effect Devices:</strong> Articulate the critical architectural distinction between <strong>MIDI Tools</strong> (non-real-time, offline clip-level data transforms) and <strong>MIDI Effect Devices</strong> (real-time, continuous DSP stream processors).","<strong>Operate the Twelve Native MIDI Transformations:</strong> Apply <strong>Arpeggiate</strong>, <strong>Chop</strong>, <strong>Connect</strong>, <strong>Glissando</strong>, <strong>LFO</strong>, <strong>Ornament</strong>, <strong>Quantize</strong>, <strong>Recombine</strong>, <strong>Span</strong>, <strong>Strum</strong>, <strong>Time Warp</strong>, and <strong>Velocity Shaper</strong> to transform existing MIDI notes.","<strong>Deploy the Five Native MIDI Generators:</strong> Construct algorithmic musical patterns from scratch using <strong>Rhythm</strong>, <strong>Seed</strong>, <strong>Shape</strong>, <strong>Stacks</strong>, and <strong>Euclidean</strong>.","<strong>Integrate Scale-Aware Tool Pipelines:</strong> Chain generators and transformations within scale-quantized harmonic contexts to generate complex, musical sequences rapidly."],"ordered":true}]}],"minutes":8},{"id":"ableton-l6-2-1-2","title":"6.2.1: MIDI Tools Architecture & Location","blocks":[{"type":"step","title":"1.1 The Clip View Tool Panels","blocks":[{"type":"prose","html":"In Live 12, MIDI Tools live inside two dedicated sub-panels within <strong>Clip View</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                           MIDI TOOLS ARCHITECTURE                           │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  CLIP VIEW -&gt; MIDI NOTE EDITOR                                              │\n│  ┌─────────────────────────────────┬──────────────────────────────────────┐ │\n│  │ 1. TRANSFORMATIONS TAB          │ 2. GENERATORS TAB                    │ │\n│  ├─────────────────────────────────┼──────────────────────────────────────┤ │\n│  │ Operates on EXISTING notes in   │ Generates NEW notes from empty       │ │\n│  │ the active clip or selection.   │ clips or replaces active selections. │ │\n│  │                                 │                                      │ │\n│  │ • Arpeggiate   • Quantize       │ • Rhythm     • Stacks                │ │\n│  │ • Chop         • Recombine      │ • Seed       • Euclidean             │ │\n│  │ • Connect      • Span           │ • Shape                              │ │\n│  │ • Glissando    • Strum          │                                      │ │\n│  │ • LFO          • Time Warp      │                                      │ │\n│  │ • Ornament     • Velocity Shaper│                                      │ │\n│  └─────────────────────────────────┴──────────────────────────────────────┘ │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"1.2 Fundamental Distinction: Tools vs. Devices","blocks":[{"type":"list","items":["<strong>MIDI Tools (Clip Level):</strong> Discrete algorithms that write or modify actual note data directly inside the clip. Once applied, the generated notes are visible, editable, and permanent in the piano roll.","<strong>MIDI Effects (Track Device Chain):</strong> Real-time devices (e.g., native <em>Arpeggiator</em>, <em>Pitch</em>, <em>Scale</em>) that intercept and alter the live MIDI stream between the clip and the synthesizer without altering the recorded notes on the clip."],"ordered":false}]}],"minutes":8},{"id":"ableton-l6-2-2","title":"6.2.2 / 6.2.3: The Twelve MIDI Transformations","blocks":[{"type":"step","title":"6.2.2 / 6.2.3: The Twelve MIDI Transformations","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                    THE 12 NATIVE MIDI TRANSFORMATIONS                       │\n├─────────────────┬───────────────────────────────────────────────────────────┤\n│ TRANSFORMATION  │ OPERATIONAL ALGORITHMIC BEHAVIOR                          │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Arpeggiate**  │ Breaks held chord blocks into ascending, descending, or   │\n│                 │ alternating arpeggiated patterns with rate/gate controls. │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Chop**        │ Slices long sustained notes into repetitive subdivisions  │\n│                 │ (e.g., cutting a whole note into 1/16th bursts).          │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Connect**     │ Fills empty gaps between disparate notes by drawing       │\n│                 │ connecting passing notes or scalar steps.                 │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Glissando**   │ Generates rapid scalar runs or pitch glides bridging two  │\n│                 │ separated target notes.                                   │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **LFO**         │ Modulates pitch, velocity, or duration of notes along a   │\n│                 │ selectable LFO curve (Sine, Triangle, Saw, Random).       │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Ornament**    │ Inset grace notes, mordents, trills, and flam flourishes  │\n│                 │ immediately preceding or following note downbeats.        │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Quantize**    │ Pulls note start times and durations toward metric grid   │\n│                 │ intersections with variable strength percentage.          │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Recombine**   │ Shuffles and permutes pitch orders, rhythmic placements,  │\n│                 │ or velocity assignments across the selected phrase.       │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Span**        │ Adjusts the legato/staccato duration of notes to extend   │\n│                 │ or truncate note lengths toward adjacent notes.           │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Strum**       │ Offsets the start times of notes within a vertical chord  │\n│                 │ stack, emulating physical guitar pick strumming.          │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Time Warp**   │ Applies non-linear acceleration or deceleration curves to │\n│                 │ rhythmic note timing across the clip.                     │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Velocity      │ Draws bezier curves across velocity values, sculpting     │\n│   Shaper**      │ crescendos, decrescendos, and rhythmic accent patterns.   │\n└─────────────────┴───────────────────────────────────────────────────────────┘</pre>"}]}],"minutes":8},{"id":"ableton-l6-2-4","title":"6.2.4: The Five MIDI Generators","blocks":[{"type":"step","title":"6.2.4: The Five MIDI Generators","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                       THE 5 NATIVE MIDI GENERATORS                          │\n├─────────────────┬───────────────────────────────────────────────────────────┤\n│ GENERATOR       │ OPERATIONAL SYNTHESIS BEHAVIOR                            │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Rhythm**      │ Generates rhythmic note bursts using density, accent,     │\n│                 │ and division parameters.                                  │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Seed**        │ Generates pseudo-randomized melodic or polyphonic note    │\n│                 │ patterns constrained by pitch range and scale rules.      │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Shape**       │ Draws ascending, descending, or undulating melodic curves │\n│                 │ mapped precisely to the active musical scale.             │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Stacks**      │ Generates harmonic chord progressions (triads, 7ths, 9ths,│\n│                 │ inversions) constrained strictly to the selected scale.   │\n├─────────────────┼───────────────────────────────────────────────────────────┤\n│ **Euclidean**   │ Distributes a specified number of rhythmic hits as evenly │\n│                 │ as possible across a metric bar (Euclidean algorithm).    │\n└─────────────────┴───────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Algorithmic Harmony &amp; Strumming Protocol:</strong>","Create a MIDI track hosting <strong>Operator</strong> (init electric piano patch).","Double-click an empty Session slot to create a 4-bar clip.","Set Global Scale in the Control Bar to <code>D Minor</code>.","In Clip View, open the <strong>Generators Tab</strong> and select <strong>Stacks</strong>.","Set Chord Complexity to <code>Triads + 7ths</code>, Voicing to <code>Root Inversion</code>, and generate an 8-chord harmonic progression.","Switch to the <strong>Transformations Tab</strong> and select <strong>Strum</strong>.","Adjust the Strum Tension slider to offset chord note starts by 15 milliseconds. Listen to the realistic plucked keyboard feel.","<strong>Euclidean Rhythm &amp; Velocity Shaping Drill:</strong>","Create a Drum Rack track. Open an empty 1-bar MIDI clip.","In Clip View, select the <code>Hi-Hat</code> row.","Open <strong>Generators -&gt; Euclidean</strong>. Set Steps to <code>16</code> and Hits to <code>7</code>. Generate the pattern.","Open <strong>Transformations -&gt; Velocity Shaper</strong>. Draw an exponential ramp curve from 40 to 110.","Play back and observe a complex, accented polyrhythmic percussion loop."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 6.1]\n[ ] Articulated the operational distinction between MIDI Tools and MIDI Effect Devices.\n[ ] Applied Strum, Chop, and Velocity Shaper transformations to an existing clip.\n[ ] Generated a multi-chord harmonic progression using Stacks constrained by scale awareness.\n[ ] Generated a polyrhythmic percussion sequence using Euclidean.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 11 (<em>MIDI Tools: 11.1 Overview, 11.2 Transformations, 11.3 Generators</em>).","<strong>Ableton Knowledgebase:</strong> <em>MIDI Tools in Live 12 FAQ</em>, <em>Algorithmic Composition with MIDI Generators</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-6-3-4","code":"6.3","title":"MIDI, Tools, Grooves, Tuning & MPE","blurb":"- Section ID: ableton-sec-6-3 - Lessons Included: ableton-l6-3-1, ableton-l6-3-2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l6-3-1","title":"Section overview","blocks":[{"type":"step","title":"Section 6.3 — MIDI Polyphonic Expression (MPE) & Per-Note Control","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-6-3</code>","<strong>Lessons Included:</strong> <code>ableton-l6-3-1</code>, <code>ableton-l6-3-2</code>","<strong>Target Skill Band:</strong> Expressive Acoustic Modeling &amp; Multi-Channel MIDI","<strong>Manual Spine References:</strong> Chapter 12 (<em>Editing MPE: 12.1–12.5</em>), Chapter 30 (<em>Live Instrument Reference: Drift MPE Integration</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard MPE Engine &amp; Hardware Topology"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Analyze the MPE Multi-Channel Architecture:</strong> Understand how MPE distributes polyphonic notes across independent MIDI channels (Channels 2–16) with a master configuration channel (Channel 1).","<strong>Operate the Three MPE Expression Dimensions:</strong> View, draw, and edit per-note <strong>Pitch Bend</strong> (glide/vibrato), <strong>Slide</strong> (vertical Y-axis / CC74 timbre), and <strong>Pressure</strong> (per-note aftertouch) inside the MIDI Note Editor.","<strong>Configure MPE in Live Devices &amp; Third-Party VSTs:</strong> Map MPE modulation destinations inside native devices (<strong>Drift</strong>, <strong>Analog</strong>, <strong>Electric</strong>) and configure multi-channel MPE reception in third-party VST3 instruments.","<strong>Differentiate Polyphonic Aftertouch from Full MPE Hardware:</strong> Distinguish standard pad polyphonic aftertouch (e.g., Novation Launchkey MK4 pad pressure) from true multi-dimensional continuous MPE hardware surfaces, avoiding MIDI port channel monopolization."],"ordered":true}]}],"minutes":8},{"id":"ableton-l6-3-1-2","title":"6.3.1: The Three Dimensions of MPE","blocks":[{"type":"step","title":"1.1 MPE Multi-Channel Channel Allocation","blocks":[{"type":"prose","html":"Traditional MIDI transmits Pitch Bend and Channel Aftertouch globally across a single MIDI channel, affecting every sounding note identically. <strong>MPE (MIDI Polyphonic Expression)</strong> overcomes this by allocating each newly struck note to a dedicated, independent MIDI channel:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                         MPE MULTI-CHANNEL TOPOLOGY                          │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  MIDI In Stream (Master Channel 1: Global Settings &amp; Pitch Bend Range)      │\n│  ├── Note 1 (C3) ──► Channel 2  [Pitch Bend: +24ct | Pressure: 92 | CC74: 40]│\n│  ├── Note 2 (E3) ──► Channel 3  [Pitch Bend: 0ct   | Pressure: 45 | CC74: 80]│\n│  └── Note 3 (G3) ──► Channel 4  [Pitch Bend: -12ct | Pressure: 110| CC74: 10]│\n│                                                                             │\n│  (Each voice in the chord sustains independent pitch bends and timbral morphs│\n│   without causing pitch interference on adjacent held notes)               │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"1.2 The Three Per-Note Expression Dimensions","blocks":[{"type":"prose","html":"Inside the MIDI Note Editor, clicking the <strong>Expression Tab</strong> reveals three per-note modulation lanes:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                          MPE EXPRESSION DIMENSIONS                          │\n├──────────────────┬──────────────────────────┬───────────────────────────────┤\n│ DIMENSION        │ MIDI SPECIFICATION       │ ACOUSTIC EXPRESSION ROLE      │\n├──────────────────┼──────────────────────────┼──────────────────────────────┤\n│ **Pitch**        │ Per-Note Pitch Bend      │ Microtonal vibrato, per-note  │\n│ (Horizontal X)   │ (14-bit resolution)      │ fretless glides, portamento.  │\n├──────────────────┼──────────────────────────┼──────────────────────────────┤\n│ **Slide**        │ Per-Note CC 74           │ Timbral morphing, filter      │\n│ (Vertical Y)     │ (7-bit / 14-bit)         │ cutoff sweeps, wavetable pos. │\n├──────────────────┼──────────────────────────┼──────────────────────────────┤\n│ **Pressure**     │ Polyphonic Aftertouch /  │ Dynamic volume swells,        │\n│ (Z-Axis / Depth) │ Channel Pressure         │ saturation drive, overtone add│\n└──────────────────┴──────────────────────────┴───────────────────────────────┘</pre>"}]}],"minutes":8},{"id":"ableton-l6-3-2","title":"6.3.2: Device Integration & Hardware Honesty","blocks":[{"type":"step","title":"6.3.2: Device Integration & Hardware Honesty","blocks":[{"type":"heading","text":"2.1 MPE Routing in Native Devices (Drift Example)","level":4},{"type":"prose","html":"In <strong>Drift</strong>, the <em>Mode</em> panel provides dedicated MPE routing matrix inputs:"},{"type":"list","items":["<strong>Pitch:</strong> Automatically handles per-note pitch bends up to the defined Pitch Bend Range (e.g., ± 48 semitones).","<strong>Pressure:</strong> Can be assigned to modulate Filter Cutoff, LFO Rate, or Oscillator 2 Level.","<strong>Slide (CC74):</strong> Can be routed to Oscillator Shape or Filter Resonance."],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                         DRIFT MPE MODULATION MATRIX                         │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [MPE Input: Pressure] ──► Amount: [+45%] ──► Destination: [Filter Cutoff]  │\n│  [MPE Input: Slide]    ──► Amount: [+80%] ──► Destination: [Osc 1 Shape]    │\n│  [MPE Input: Pitch]    ──► Range:  [+/- 12st]──► Destination: [Voice Pitch] │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"heading","text":"2.2 Hardware Topology: Polyphonic Aftertouch vs. True MPE","level":4},{"type":"prose","html":"It is critical to maintain hardware honesty regarding studio controllers:"},{"type":"list","items":["<strong>True MPE Controllers (e.g., Roli Seaboard, LinnStrument):</strong> Provide continuous X/Y/Z tracking across every key.","<strong>Polyphonic Aftertouch Controllers (e.g., Novation Launchkey MK4 Pads):</strong> Transmit <strong>Pressure (Z-axis)</strong> per pad, but do not provide horizontal finger glides (X-axis) or vertical key slides (Y-axis).","<strong>Studio Precaution:</strong> In <code>Settings -&gt; Link / Tempo / MIDI</code>, do not enable the global <strong>MPE</strong> flag on standard MIDI controller ports unless the connected hardware explicitly broadcasts multi-channel MPE. Enabling MPE on generic ports can monopolize MIDI channels 1–16 and break Channel-10 Drum Rack triggers."],"ordered":false}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Drawing Per-Note MPE Envelopes:</strong>","Create a MIDI track hosting <strong>Drift</strong>. Load the default subtractive init patch.","In Clip View, draw a 2-bar C Major chord (notes <code>C3</code>, <code>E3</code>, <code>G3</code>).","Click the <strong>Expression Tab</strong> (wavy line icon) in Clip View.","Select the <code>Pitch</code> dimension. Click on note <code>E3</code> and draw an upward curve bending the third up to an <code>F3</code> (suspended 4th), while <code>C3</code> and <code>G3</code> remain perfectly stationary.","Select the <code>Pressure</code> dimension. Draw an ascending swell on note <code>C3</code> only.","In Drift, map Pressure to Filter Cutoff. Play back the clip and listen to the single-note filter sweep and single-note pitch bend occurring simultaneously inside the chord.","<strong>Third-Party Plugin MPE Configuration:</strong>","Load an MPE-compatible VST3 synth (e.g., Surge XT).","Click the small downward arrow on the device header to open the plugin configuration panel.","Right-click the device header and ensure <strong>Enable MPE</strong> is checked.","Set the MPE Pitch Bend Range in Live to match the plugin's internal setting (typically 48 semitones)."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 6.2]\n[ ] Defined the multi-channel operational architecture of MPE.\n[ ] Drawn independent per-note Pitch Bend and Pressure curves on a single chord.\n[ ] Routed MPE Pressure and Slide to sonic destinations inside Drift.\n[ ] Can state the technical difference between Polyphonic Aftertouch and a full MPE surface.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 12 (<em>Editing MPE: 12.1 Layout, 12.2 MPE Dimensions, 12.3 MPE in Live Devices</em>), Chapter 30 (<em>Live Instrument Reference: 30.3 Drift</em>).","<strong>Ableton Knowledgebase:</strong> <em>Using MPE in Live 12</em>, <em>MPE Configuration for VST3 Plugins</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-6-4-5","code":"6.4","title":"MIDI, Tools, Grooves, Tuning & MPE","blurb":"- Section ID: ableton-sec-6-4 - Lessons Included: ableton-l6-4-1, ableton-l6-4-2, ableton-l6-4-3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l6-4-1","title":"Section overview","blocks":[{"type":"step","title":"Section 6.4 — The Groove Pool & Microtonal Tuning Systems","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-6-4</code>","<strong>Lessons Included:</strong> <code>ableton-l6-4-1</code>, <code>ableton-l6-4-2</code>, <code>ableton-l6-4-3</code>","<strong>Target Skill Band:</strong> Micro-Timing Sculpting &amp; Microtonal Harmonic Systems","<strong>Manual Spine References:</strong> Chapter 14 (<em>Using Grooves: 14.1–14.5</em>), Chapter 15 (<em>Using Tuning Systems: 15.1–15.4</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Groove Engine &amp; Scala Tuning Subsystem"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Operate the Groove Pool Interface:</strong> Manage the global <strong>Groove Pool</strong> (<code>Ctrl+Alt+G</code>), assign groove templates (<code>.agr</code>) to audio and MIDI clips, and adjust <strong>Base</strong>, <strong>Timing</strong>, <strong>Random</strong>, and <strong>Velocity</strong> influence parameters.","<strong>Execute Non-Destructive Feel Sculpting vs. Groove Commits:</strong> Treat groove templates as non-destructive real-time swing quantizers, and execute the <strong>Commit</strong> command to print micro-timing offsets directly into clip note data.","<strong>Implement Microtonal Tuning Systems:</strong> Load standard Scala (<code>.scl</code>) and native tuning system presets into the Control Bar, evaluate historical temperaments and microtonal scales, and bypass tuning systems on dedicated percussive tracks."],"ordered":true}]}],"minutes":8},{"id":"ableton-l6-4-1-2","title":"6.4.1 / 6.4.2: The Groove Pool Engine","blocks":[{"type":"step","title":"1.1 The Groove Pool Topology","blocks":[{"type":"prose","html":"The <strong>Groove Pool</strong> is opened by clicking the wavy groove icon at the bottom of the Browser or pressing <code>Ctrl+Alt+G</code>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                           THE GROOVE POOL TOPOLOGY                          │\n├───────────────────┬──────────┬──────────┬──────────┬──────────┬─────────────┤\n│ GROOVE TEMPLATE   │ BASE     │ TIMING   │ RANDOM   │ VELOCITY │ COMMIT      │\n├───────────────────┼──────────┼──────────┼──────────┼──────────┼─────────────┤\n│ MPC 16 Swing-63   │ 1/16     │ 75%      │ 5%       │ 40%      │ [ Commit ]  │\n│ Logic 8-Swing D   │ 1/8      │ 100%     │ 0%       │ 20%      │ [ Commit ]  │\n│ Live Acoustic Drm │ 1/16     │ 60%      │ 12%      │ 80%      │ [ Commit ]  │\n├───────────────────┴──────────┴──────────┴──────────┴──────────┴─────────────┤\n│ Global Groove Amount: [====================|====] 100%                      │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"1.2 Parameter Mechanics & The Mathematics of Swing","blocks":[{"type":"list","items":["<strong>Base Division:</strong> Sets the metric grid unit across which the groove operates (typically <code>1/16</code> or <code>1/8</code>).","<strong>Timing Amount (0% to 100%):</strong> Determines how far notes or audio transients are shifted toward the groove's micro-timing offsets. At 0%, playback is mathematically straight; at 100%, playback matches the groove template perfectly.","<strong>Random Amount (0% to 100%):</strong> Introduces controlled gaussian jitter to note onset timing, simulating human timing imperfection.","<strong>Velocity Amount (0% to 100%):</strong> Scales incoming note velocities according to the groove template's dynamic volume envelope.","<strong>Global Amount Slider:</strong> Acts as a master wet/dry macro for all active grooves across the entire Live Set."],"ordered":false}]},{"type":"step","title":"1.3 Non-Destructive Playback vs. Committing","blocks":[{"type":"list","items":["<strong>Real-Time Groove Playback:</strong> Assigning a groove to a clip's <strong>Groove Slot</strong> applies micro-timing during audio playback without altering the visual positions of notes or warp markers.","<strong>Commit (<code>Commit</code> button in Clip View):</strong> Writes the groove's timing offsets and velocity changes permanently into the MIDI notes or audio Warp markers, resetting the clip's groove slot to <code>None</code>."],"ordered":false}]}],"minutes":8},{"id":"ableton-l6-4-3","title":"6.4.3: Tuning Systems & Scala Support","blocks":[{"type":"step","title":"6.4.3: Tuning Systems & Scala Support","blocks":[{"type":"heading","text":"2.1 Microtonal Scales & Temperament Architecture","level":4},{"type":"prose","html":"Live 12 introduces native support for <strong>Tuning Systems</strong>, breaking the historical constraint of 12-Tone Equal Temperament (12-TET):"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                     TUNING SYSTEMS SIGNAL FLOW &amp; BYPASS                     │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  CONTROL BAR: Global Tuning System Active (e.g., \"Just Intonation - C\")     │\n│       │                                                                     │\n│       ├──► Track 1 (Drift Poly Synth)   ──► RETUNED (Plays Just Intonation) │\n│       ├──► Track 2 (Operator FM Pad)    ──► RETUNED (Plays Just Intonation) │\n│       └──► Track 3 (Drum Rack Perc)     ──► [BYPASS TUNING: ON]             │\n│                                             └──► Preserves standard pitch   │\n│                                                  triggers on standard pads  │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"heading","text":"2.2 Scala (.scl) & Native Library Files","level":4},{"type":"list","items":["<strong>Loading a Tuning:</strong> In the Browser, navigate to <code>Tuning Systems</code> (or drag any <code>.scl</code> file directly into Live).","<strong>Scale Mapping in Control Bar:</strong> Live remaps pitch calculation across all native instruments (<strong>Drift</strong>, <strong>Operator</strong>, <strong>Analog</strong>, <strong>Electric</strong>, <strong>Tension</strong>, <strong>Collision</strong>) and MPE-enabled third-party plugins.","<strong>Bypassing Tuning per Track:</strong> On drum kits and unpitched percussion tracks, right-click the track title bar and select <strong>Bypass Tuning System</strong> to prevent drum samples from transposing off their expected standard trigger pitches."],"ordered":false}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Extracting and Applying an MPC Swing Groove:</strong>","Drag a rigid, robotic 1/16th note hi-hat MIDI clip onto a track.","Open the Groove Pool (<code>Ctrl+Alt+G</code>).","In the Browser, navigate to <code>Core Library -&gt; Grooves -&gt; MPC</code> and drag <code>MPC 16 Swing-62.agr</code> into the Groove Pool.","In the hi-hat Clip View, select <code>MPC 16 Swing-62</code> in the <strong>Groove Chooser</strong>.","Play back. Gradually adjust the <strong>Timing</strong> slider in the Groove Pool from 0% to 100% to hear the robotic rhythm relax into a deep hip-hop pocket.","Click the <strong>Commit</strong> button next to the Groove Chooser in Clip View. Confirm that the notes on the piano roll visibly shift to reflect the swing offsets.","<strong>Microtonal Tuning Exploration:</strong>","In the Browser, navigate to <code>Tuning Systems</code> and load <code>Quarter-Tone 24-EDO.ascl</code>.","On a Drift synth track, play chromatic ascending notes using the Computer MIDI Keyboard. Listen to the 24 microtonal subdivisions per octave.","Create a Drum Rack track. Right-click the track header and enable <strong>Bypass Tuning System</strong>. Confirm that drum pad mapping remains standard."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 6.3]\n[ ] Fluent with Groove Pool operations (Base, Timing, Random, Velocity).\n[ ] Successfully applied a groove template to a MIDI clip and executed a Commit.\n[ ] Loaded an alternative Tuning System from the browser.\n[ ] Verified that native instruments retune automatically while bypassed drum tracks preserve pad mapping.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 14 (<em>Using Grooves: 14.1–14.5</em>), Chapter 15 (<em>Using Tuning Systems: 15.1–15.4</em>).","<strong>Ableton Knowledgebase:</strong> <em>Using the Groove Pool in Live 12</em>, <em>Tuning Systems and Scala FAQ</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
